// Normalize RSS item + compute stable SHA-256 hash for deduping
// Mode: Run Once for Each Item -> one output article per input article.

const crypto = require('crypto');

function normalizeWhitespace(s) {
  return String(s || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonicalUrl(url) {
  // Remove common tracking params so hashes stay stable.
  try {
    const u = new URL(String(url || '').trim());
    const drop = new Set([
      'utm_source','utm_medium','utm_campaign','utm_term','utm_content',
      'at_medium','at_campaign','at_custom1','at_custom2','at_custom3',
      'fbclid','gclid','igshid','mc_cid','mc_eid'
    ]);

    [...u.searchParams.keys()].forEach(k => {
      if (drop.has(k.toLowerCase())) u.searchParams.delete(k);
    });

    const params = [...u.searchParams.entries()].sort(([a],[b]) => a.localeCompare(b));
    u.search = '';
    for (const [k, v] of params) u.searchParams.append(k, v);

    u.pathname = u.pathname.replace(/\/+$/, '');

    return u.toString();
  } catch {
    return String(url || '').trim();
  }
}

function sha256Hex(input) {
  return crypto.createHash('sha256').update(input, 'utf8').digest('hex');
}

function pickFirst(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

// Crash-proof date parsing: never lets toISOString() throw "Invalid time value".
function safeIsoDate(v, fallbackIso) {
  if (v === undefined || v === null) return fallbackIso;
  if (typeof v === 'object') v = v['#text'] ?? v['_'] ?? '';
  const s = String(v).trim();
  if (!s) return fallbackIso;
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? fallbackIso : d.toISOString();
}

// --------- INPUT MAPPING ---------
const rawTitle = pickFirst($json.title, $json.raw_title, $json.headline, $json.title_uk);
const rawSummary = pickFirst($json.contentSnippet, $json.summary, $json.raw_content, $json.description, $json.summary_uk);
const rawLink = pickFirst($json.link, $json.url, $json.raw_link, $json.source_url);

const feed = ($json.__feed && typeof $json.__feed === 'object') ? $json.__feed : {};
const source_id = pickFirst($json.source_id, feed.source_id);
const primary_sector = pickFirst($json.primary_sector, feed.primary_sector, 'infrastructure');

// Published date: parse safely, fall back to ingestion time if unparseable
const published_date = safeIsoDate(
  pickFirst($json.isoDate, $json.pubDate, $json.published_date),
  new Date().toISOString()
);

const titleNorm = normalizeWhitespace(rawTitle);
const summaryNorm = normalizeWhitespace(rawSummary);
const urlCanon = canonicalUrl(rawLink);

const hashMaterial = [
  'v1',
  source_id || '',
  urlCanon,
  titleNorm.toLowerCase(),
  summaryNorm.toLowerCase()
].join('|');

const n8n_content_hash = sha256Hex(hashMaterial);

// --------- OUTPUT OBJECT ---------
const out = {
  title_uk: titleNorm,
  summary_uk: summaryNorm,

  published_date,
  source_url: urlCanon,
  primary_sector,
  source_id: source_id || null,

  article_type: pickFirst($json.article_type, 'news'),
  secondary_sectors: Array.isArray($json.secondary_sectors) ? $json.secondary_sectors : [],
  credibility_tier: Number.isFinite($json.credibility_tier) ? $json.credibility_tier : (feed.source_credibility_tier ?? 2),
  original_language: pickFirst($json.original_language, feed.language, 'uk'),
  translation_status: pickFirst($json.translation_status, 'machine'),

  n8n_content_hash,
  content_hash: n8n_content_hash,

  __feed: feed
};

return { json: out };

const feed = $node["Loop Over Items"].json;

return $input.all().map((item) => ({
  json: {
    ...item.json,
    __feed: {
      source_id: feed.id,
      stakeholder_id: feed.stakeholder_id,
      source_name: feed.name_en,
      source_credibility_tier: feed.credibility_tier ?? 2,
      source_verification_status: feed.verification_status ?? "pending",
      primary_sector: feed.primary_sector ?? feed.default_primary_sector ?? null,
      language: feed.language ?? "uk"
    }
  }
}));

const channel = $json?.rss?.channel;
const ch = Array.isArray(channel) ? channel[0] : channel;

// RSS 2.0: <rss><channel><item>
let items = ch?.item ?? [];
if (!Array.isArray(items)) items = [items];

// Atom fallback: <feed><entry>
if (items.length === 0) {
  let entries = $json?.feed?.entry ?? [];
  if (!Array.isArray(entries)) entries = [entries];
  items = entries;
}

// XML values can be plain strings or objects like {'#text': '...'} / {'_': '...'}
// (happens when an element has attributes, e.g. <guid isPermaLink="true">).
function txt(v) {
  if (v === undefined || v === null) return '';
  if (typeof v === 'object') return String(v['#text'] ?? v['_'] ?? '').trim();
  return String(v).trim();
}

// Atom links live in an href attribute: <link href="..."/>
function linkOf(it) {
  const l = it.link;
  if (!l) return '';
  const first = Array.isArray(l) ? l[0] : l;
  if (typeof first === 'object') {
    return String(first['#text'] ?? first['_'] ?? first?.$?.href ?? first?.href ?? '').trim();
  }
  return String(first).trim();
}

const out = items
  .map((it) => ({
    json: {
      title: txt(it.title),
      link: linkOf(it),
      description: txt(it.description ?? it.summary ?? it.content),
      guid: txt(it.guid ?? it.id) || null,
      pubDate: txt(it.pubDate ?? it.published ?? it.updated) || null
    }
  }))
  .filter((it) => it.json.title || it.json.link);

// Sentinel: fetch failed, page wasn't a feed, or feed was empty.
// Emit one flagged item so the loop continues instead of stalling the run.
if (out.length === 0) {
  return [{ json: { __no_items: true, __feed_url: $('Loop Over Items').item?.json?.rss_feed_url ?? null } }];
}

return out;

const feed = $json;

// hard requirement: stakeholder_id must exist
if (!feed.stakeholder_id) {
  feed.__skip_feed = true;
  feed.__skip_reason = `Missing stakeholder_id for source ${feed.id} (${feed.name_en})`;
}

return [{ json: feed }];

/**
 * Relevance filter (v2)
 * - Marks items keep/drop but DOES NOT silently kill the workflow
 * - Keeps UA humanitarian / conflict / governance / donor / reconstruction signals
 * - Fail-open if nothing is kept (prevents "workflow stops")
 */

function safeStr(v) { return (v ?? "").toString().trim(); }
function lower(v) { return safeStr(v).toLowerCase(); }
function tryParseUrl(u) { try { return new URL(u); } catch { return null; } }
function domainFromUrl(u) {
  const parsed = tryParseUrl(u);
  return parsed ? parsed.hostname.replace(/^www\./, "").toLowerCase() : "";
}
function includesAny(text, needles) {
  for (const n of needles) if (text.includes(n)) return true;
  return false;
}
function countMatches(text, needles) {
  let c = 0;
  for (const n of needles) if (text.includes(n)) c++;
  return c;
}

// --- CONFIG ---
const THRESHOLD_KEEP = 7;          // was 6 (too strict)
const UA_ONLY_KEEP_MIN = 2;        // if Ukraine is mentioned at all, keep at least some
const FAIL_OPEN = true;

// Keep your existing lists (trimmed here for brevity) + ADD humanitarian/conflict terms
const UA_CORE = [
  "ukraine","ukrainian","kyiv","kiev","kharkiv","dnipro","odesa","lviv","mykolaiv",
  "zaporizhzhia","sumy","chernihiv","donetsk","luhansk","mariupol","kherson","crimea","donbas",
  "ukrenergo","naftogaz"
];

const RECON = [
  "reconstruction","rebuild","recovery","restoration","repair","damaged","destroyed","demining",
  "housing","shelter","schools","hospitals","infrastructure","critical infrastructure","utilities",
  "water","wastewater","sewage","heating","power grid","electricity","bridge","rail","road","port",
  "urban","municipal","community","hromada","resilience"
];

const DONORS_FINANCE = [
  "world bank","ebrd","eib","imf","undp","unops","unicef","who","oecd",
  "eu","european commission","g7","usaid","giz","kfw","sida","norad",
  "donor","grant","loan","financing","funding","procurement","tender","contract"
];

// NEW: humanitarian/conflict/rights terms (these are common in UN News “briefs”)
const HUMANITARIAN = [
  "humanitarian","aid","relief","emergency","displaced","displacement","refugee","asylum",
  "civilian","casualties","attack","shelling","missile","airstrike","frontline",
  "evacuation","food","famine","hunger","nutrition","cholera","epidemic"
];

const GOV_REFORMS = [
  "reform","decentralization","anti-corruption","transparency","audit","oversight",
  "public procurement","open data","e-governance","digitalization"
];

const NOISE = [
  "celebrity","gossip","movie","music","grammy","oscar","football","soccer","nba","recipe","fashion"
];

function evaluateItem(item) {
  const j = item.json;

  const title = lower(j.title_uk || j.title_en || j.title || "");
  const summary = lower(j.summary_en || j.summary_uk || j.content_en || j.content_uk || j.description || "");
  const url = safeStr(j.source_url || j.link || j.article_url || j.url || ""); // IMPORTANT: include link
  const domain = domainFromUrl(url);

  const fullText = `${title}\n${summary}`;

  let score = 0;
  const reasons = [];

  const noiseCount = countMatches(fullText, NOISE);
  if (noiseCount) { score -= 3 * noiseCount; reasons.push(`Noise x${noiseCount} (-${3*noiseCount})`); }

  const uaCount = countMatches(fullText, UA_CORE);
  if (uaCount) { score += Math.min(6, uaCount * 2); reasons.push(`UA x${uaCount} (+${Math.min(6, uaCount*2)})`); }

  const reconCount = countMatches(fullText, RECON);
  if (reconCount) { score += Math.min(8, reconCount * 2); reasons.push(`Recon x${reconCount} (+${Math.min(8, reconCount*2)})`); }

  const donorCount = countMatches(fullText, DONORS_FINANCE);
  if (donorCount) { score += Math.min(6, donorCount * 2); reasons.push(`Donor x${donorCount} (+${Math.min(6, donorCount*2)})`); }

  const humCount = countMatches(fullText, HUMANITARIAN);
  if (humCount) { score += Math.min(6, humCount); reasons.push(`Humanitarian x${humCount} (+${Math.min(6, humCount)})`); }

  const govRefCount = countMatches(fullText, GOV_REFORMS);
  if (govRefCount) { score += Math.min(4, govRefCount * 2); reasons.push(`Gov/Reform x${govRefCount} (+${Math.min(4, govRefCount*2)})`); }

  const hasUA = uaCount > 0;
  const keep =
    score >= THRESHOLD_KEEP ||
    (hasUA && score >= UA_ONLY_KEEP_MIN) ||           // Ukraine mention alone can pass
    (hasUA && (reconCount || donorCount || humCount)); // Ukraine + any strong theme

  const bucket =
    keep ? (reconCount ? "ua_recon" : humCount ? "ua_humanitarian" : "score_keep") : "drop";

  return { keep, score, bucket, reasons, domain };
}

// Evaluate all, but do NOT drop them yet
const all = $input.all();
const kept = [];

for (const item of all) {
  const res = evaluateItem(item);
  item.json.__decision = res.keep ? "keep" : "drop";
  item.json.__relevance_score = res.score;
  item.json.__relevance_bucket = res.bucket;
  item.json.__relevance_reasons = res.reasons;
  if (res.keep) kept.push(item);
}

// Fail-open: if we kept nothing, pass everything through so workflow continues
if (FAIL_OPEN && kept.length === 0) {
  for (const item of all) {
    item.json.__decision = "keep_fallback";
    item.json.__relevance_bucket = "fail_open";
    item.json.__relevance_reasons = ["Fail-open: kept=0, passing through all items"];
  }
  return all;
}

// Otherwise, return only kept (same behavior as before, but far less brittle)
return kept;

// Mode: Run Once for Each Item.
// The AI Agent's output item usually contains ONLY { output: "..." } --
// the original article fields must be read from the paired item that went
// INTO the agent (output of "Code in JavaScript4").

function stripFences(s) {
  return String(s || "")
    .trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();
}

function safeParseJsonString(s) {
  const cleaned = stripFences(s);
  try {
    const parsed = JSON.parse(cleaned);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) return parsed;
    return null;
  } catch {
    return null;
  }
}

const agentItem = ($json && typeof $json === "object" && !Array.isArray($json)) ? $json : {};

let base = {};
try {
  base = $('Code in JavaScript4').item?.json ?? {};
} catch {
  base = {};
}

const aiRaw = agentItem.output ?? agentItem.text ?? agentItem.response ?? "";
const ai = safeParseJsonString(aiRaw) || {};

const out = {
  title_uk: base.title_uk ?? "",
  summary_uk: base.summary_uk ?? "",

  title_en: ai.title_en ?? "",
  title_de: ai.title_de ?? "",
  summary_en: ai.summary_en ?? "",
  summary_de: ai.summary_de ?? "",

  primary_sector: ai.primary_sector ?? base.primary_sector ?? "supply-infrastructure",
  translation_status: ai.translation_status ?? "machine",

  article_type: base.article_type ?? "news",
  published_date: base.published_date ?? new Date().toISOString(),
  source_url: base.source_url ?? "",
  source_id: base.source_id ?? null,
  secondary_sectors: Array.isArray(base.secondary_sectors) ? base.secondary_sectors : [],
  credibility_tier: Number.isFinite(base.credibility_tier) ? base.credibility_tier : 2,
  original_language: base.original_language ?? "uk",
  content_hash: base.content_hash ?? base.n8n_content_hash ?? null,

  processing_status: base.processing_status ?? "ready_for_review",
  requires_review: base.requires_review ?? false
};

// Allowed sectors -- must match exactly what the AI Agent prompt asks for.
const allowed = new Set(["housing","supply-infrastructure","urban-resilience","disaster-risk-management"]);
if (!allowed.has(out.primary_sector)) {
  out.primary_sector = "supply-infrastructure";
  out.requires_review = true;
  out.processing_status = "needs_enrichment";
  out.review_reason = "invalid_primary_sector_from_ai";
}

if (!out.title_en || !out.title_de || !out.summary_en || !out.summary_de) {
  out.requires_review = true;
  out.processing_status = "needs_enrichment";
  out.review_reason = out.review_reason ?? "ai_missing_required_fields";
}

return { json: out };

// Input: rows returned by "Get many rows" (existing DB articles whose
// n8n_content_hash matched one of this batch's hashes; may be a single
// empty item when Always Output Data kicks in with no matches).
// Output: EVERY normalized article, flagged with __is_duplicate.

const found = new Set(
  $input.all()
    .map(i => i.json?.n8n_content_hash ?? i.json?.content_hash)
    .filter(Boolean)
);

return $('Normalize RSS Items').all().map(item => ({
  json: {
    ...item.json,
    __is_duplicate: found.has(item.json.n8n_content_hash)
  }
}));

return items.filter(item => {
  // Drop items that only contain the duplicate flag
  if (!item.json) return false;

  const keys = Object.keys(item.json);

  // If the item ONLY contains the duplicate flag, remove it
  if (keys.length === 1 && keys[0] === '__is_duplicate') {
    return false;
  }

  // Keep everything else
  return true;
});
